/** Optional authoring step: node design_system/scripts/build-pages.mjs
 * Uses only Node built-ins and files inside this directory. The generated HTML
 * is the deliverable and works directly without Node, Astro or a dev server. */
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const tokens=JSON.parse(await fs.readFile(path.join(root,'tokens.json'),'utf8'));
// Group similar campaign shades in the UI; preserve the source themes for existing layouts.
const paletteNames=[['teal_asimov','Teal'],['cyan_asimov','Ciano'],['formacao_analista_dados','Laranja'],['formacao_ai_designer','Azul'],['trilha_python_web','Vermelho'],['trilha_engenharia_dados','Verde'],['trilha_data_science_ml','Terracota'],['trilha_visao_computacional','Roxo']];
const themeOptions=paletteNames.map(([id,label])=>`<option value="${id}">${label}</option>`).join('');
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const paths={
 arrow:'<path d="M5 12h14m-7-7 7 7-7 7"/>',check:'<path d="m20 6-11 11-5-5"/>',play:'<path d="M5 5a2 2 0 0 1 3.008-1.728l11.997 6.998a2 2 0 0 1 .003 3.458l-12 7A2 2 0 0 1 5 19z"/>',plus:'<path d="M5 12h14M12 5v14"/>',chevron:'<path d="m6 9 6 6 6-6"/>',right:'<path d="m9 18 6-6-6-6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',
 layers:'<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-13-2 16"/>',
 spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Zm7 0v4m-2-2h4"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7l1-7Z"/>',chart:'<path d="M4 3v17h17M8 14l4-4 4 2 5-7"/>',cpu:'<rect x="6" y="6" width="12" height="12" rx="3"/><rect x="9" y="9" width="6" height="6" rx="1"/><path d="M9 3v3m6-3v3M9 18v3m6-3v3M3 9h3m-3 6h3m12-6h3m-3 6h3"/>',
 palette:'<path d="M12 3a9 9 0 1 0 0 18h1a2 2 0 0 0 1-3.7c-1-.6-.6-2.3.6-2.3H18a4 4 0 0 0 3-4c0-4-4-8-9-8Z"/><circle cx="7" cy="10" r=".5"/><circle cx="10" cy="6.5" r=".5"/><circle cx="15" cy="7" r=".5"/><circle cx="18" cy="10.5" r=".5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
 globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',
 settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3" fill="#0b1213"/><circle cx="16" cy="17" r="3" fill="#0b1213"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7Z"/>',
 book:'<path d="M12 5C8 2 3 3 3 3v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2v16"/>',message:'<path d="M21 11a9 9 0 0 1-9 9 10 10 0 0 1-4-.8L3 21l1.7-5A9 9 0 1 1 21 11Z"/><path d="M8 11h8M8 8h5"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M4 5V4l13-2v3m4 6h-6v5h6"/>',infinity:'<path d="M12 12C8 5 3 5 3 12s5 7 9 0 9-7 9 0-5 7-9 0Z"/>',
 monitor:'<rect x="3" y="3" width="18" height="13" rx="2"/><path d="M8 21h8m-4-5v5"/>',rain:'<path d="m8 15-2 5m7-5-2 5m7-5-2 5M5 13a4 4 0 0 1-.5-8A6 6 0 0 1 16 5a4 4 0 0 1 3 8"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',type:'<path d="M4 4h16M12 4v16m-4 0h8"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v2"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>'
};
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.spark}</svg>`;
const glow=(label,href='components.html',attrs='')=>`<a class="button-glow" href="${href}" ${attrs}><span class="button-glow__border" aria-hidden="true"><span class="button-glow__border-spin"></span></span><span class="button-glow__inner" aria-hidden="true"></span><span class="button-glow__row"><span class="button-glow__icon">${icon('play')}</span><span class="button-glow__label">${label}</span><span class="button-glow__arrow">${icon('arrow')}</span></span></a>`;
const button=(label,kind='',attrs='',glyph='')=>`<button type="button" class="btn ${kind}" ${attrs}>${glyph?icon(glyph):''}${label}</button>`;
const badge=(text,kind='accent')=>`<span class="badge badge--${kind}">${text}</span>`;
const heading=(number,kicker,title,desc)=>`<header class="section-head reveal"><div><p class="eyebrow"><span class="section-index">${number} /</span> ${kicker}</p><h2>${title}</h2></div><p class="text-copy">${desc}</p></header>`;
const course=(title,text,glyph,theme='teal_asimov',meta='Explore o componente',href='components.html#cards')=>{const t=theme?tokens.themes[theme]:Object.fromEntries(['accent','accent-dark','accent-light','accent-glow'].map(key=>[key,`var(--ui-${key})`]));return `<a href="${href}" class="course-card" style="--card-accent:${t.accent};--card-accent-dark:${t['accent-dark']};--card-accent-light:${t['accent-light']};--card-accent-glow:${t['accent-glow']}"><span class="course-card__beam" aria-hidden="true"></span><span class="course-card__glow" aria-hidden="true"></span><span class="course-card__dots" aria-hidden="true"></span><span class="course-card__icon">${icon(glyph)}</span><h3 class="course-card__title">${title}</h3><p class="course-card__text">${text}</p><span class="course-card__duration">${icon('clock')} ${meta}</span></a>`;};
const benefit=(title,text,glyph,variant='base')=>`<article class="trail-overview-v2-card" data-accent-variant="${variant}"><span class="trail-overview-v2-card__shine" aria-hidden="true"></span><span class="trail-overview-v2-card__grid" aria-hidden="true"></span><div class="trail-overview-v2-card__icon-stage" aria-hidden="true"><span class="trail-overview-v2-card__icon-pedestal"></span><span class="trail-overview-v2-card__icon-halo"></span><span class="trail-overview-v2-card__icon-ring"></span>${icon(glyph,'trail-overview-v2-card__icon')}</div><h3 class="trail-overview-v2-card__title">${title}</h3><p class="trail-overview-v2-card__text">${text}</p></article>`;
const instructor=(name,role,file,bio)=>`<article class="instructor-card" tabindex="0" aria-label="${name}. Foco ou toque para conhecer."><div class="instructor-card__default"><img class="instructor-card__photo" src="assets/images/instructor-${file}.webp" alt="${name}" loading="lazy" width="300" height="400"><div class="instructor-card__overlay"></div><div class="instructor-card__info"><h3 class="instructor-card__name">${name}</h3><p class="instructor-card__role">${role}</p></div></div><div class="instructor-card__hover"><div class="instructor-card__pattern"></div><div class="instructor-card__hover-content"><div><h3 class="instructor-card__name">${name}</h3><p class="instructor-card__role">${role}</p></div><p class="instructor-card__bio">${bio}</p>${icon('arrow')}</div></div></article>`;
const avatars=()=>`<div class="avatar-stack">${[1,2,3,4,5,6].map(i=>`<img src="assets/images/avatar-${i}.webp" alt="" width="30" height="30" loading="lazy">`).join('')}</div>`;
const social=()=>`<div class="hero-social-proof"><div class="hero-social-proof__group"><div class="hero-social-proof__avatars">${[1,2,3,4,5,6].map(i=>`<img class="hero-social-proof__avatar" src="assets/images/avatar-${i}.webp" alt="" width="32" height="32" loading="lazy">`).join('')}</div><div class="hero-social-proof__copy"><p class="hero-social-proof__line1"><strong class="hero-social-proof__highlight">+30 mil alunos</strong> já</p><p class="hero-social-proof__line2">passaram por aqui</p></div></div></div>`;
let sequence=0;
function guarantee(){const id='seal-'+(++sequence);return `<section class="guarantee-card"><div class="guarantee-seal" aria-hidden="true"><span class="guarantee-seal__ring"></span><span class="guarantee-seal__text"><svg viewBox="0 0 200 200"><defs><path id="${id}" d="M100,100 m-85,0 a85,85 0 1,1 170,0 a85,85 0 1,1 -170,0"/></defs><text><textPath href="#${id}" startOffset="0%">GARANTIA DE 7 DIAS · EXEMPLO DE COMPONENTE · GARANTIA DE 7 DIAS · EXEMPLO DE COMPONENTE · </textPath></text></svg></span><div class="guarantee-seal__core">${icon('shield','guarantee-seal__icon')}<span class="guarantee-seal__label">7 DIAS</span></div></div><div class="guarantee-card__content"><p class="guarantee-card__eyebrow">Exemplo de garantia</p><h3 class="guarantee-card__title">Informações sobre garantia.</h3><p class="guarantee-card__description">Componente para apresentar prazo, condições e procedimento de solicitação. Substitua os textos pelas regras do produto.</p><div class="guarantee-steps"><div class="guarantee-step"><span class="guarantee-step__number">01 / PRAZO</span><p class="guarantee-step__text">Informe o prazo aplicável.</p></div><div class="guarantee-step"><span class="guarantee-step__number">02 / CONDIÇÕES</span><p class="guarantee-step__text">Descreva as condições.</p></div><div class="guarantee-step"><span class="guarantee-step__number">03 / SOLICITAÇÃO</span><p class="guarantee-step__text">Indique o canal de contato.</p></div></div></div></section>`;}
function pricing(){return `<div class="index4-cadence index4-typography-lumina pricing-demo" data-pricing><div class="segmented price-switch" aria-label="Período de cobrança"><button type="button" data-billing="monthly" aria-pressed="false">Mensal</button><button type="button" data-billing="annual" aria-pressed="true">Anual <span class="accent">−20%</span></button></div><div class="index4-pricing-grid">${[['Essencial','29','23','Exemplo de plano com recursos básicos.',false],['Professional','79','63','Exemplo de plano com recursos adicionais.',true]].map(([name,monthly,annual,desc,featured])=>`<article class="index4-pricing-card ${featured?'index4-pricing-card--featured':''}">${featured?'<span class="index4-pricing-card__popular">Plano em destaque</span>':''}<div class="index4-pricing-card__head"><div><h3 class="index4-pricing-card__name">${name}</h3><p class="muted" style="font-size:12px;margin:9px 0 0">${desc}</p></div><span class="index4-pricing-card__icon">${icon(featured?'spark':'layers')}</span></div><div class="index4-pricing-card__price-block"><p class="index4-pricing-card__price"><span class="index4-pricing-card__installments">R$</span><span class="index4-pricing-card__amount" data-monthly="${monthly}" data-annual="${annual}">${annual}</span><span class="muted" style="font-size:12px">/ mês</span></p><p class="index4-pricing-card__cash" data-billing-note>Cobrado anualmente · valor ilustrativo</p></div><ul class="index4-pricing-card__benefits">${[featured?'Tudo do plano Essencial':'Biblioteca de componentes','Layouts responsivos','Paletas e tipografia',featured?'Dashboards e aplicações':'Efeitos e animações',featured?'Configurações de interface':'Arquivos de referência'].map(s=>`<li class="index4-pricing-card__benefit"><span class="index4-pricing-card__check">${icon('check')}</span><span class="index4-pricing-card__benefit-text">${s}</span></li>`).join('')}</ul><div class="index4-pricing-card__footer"><button type="button" class="index4-pricing-card__cta index4-pricing-card__cta--${featured?'primary':'outline'}" data-plan="${name}">Selecionar ${name} ${icon('arrow')}</button><p class="index4-pricing-card__guarantee">${icon('shield')} Demonstração de interface</p></div></article>`).join('')}</div></div>`;}
function chart(){const id='chart-'+(++sequence);return `<div class="chart-panel"><div class="row between"><h4>Crescimento da comunidade</h4><div class="row"><span class="status-dot accent"></span><small>Alunos ativos</small></div></div><div class="chart-visual"><div class="chart-scale"><span>3.000</span><span>2.000</span><span>1.000</span><span>0</span></div><svg class="chart-svg" viewBox="0 0 600 180" role="img" aria-label="Gráfico ilustrativo: alunos ativos sobem de 680 para 2.840 ao longo do período"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--ui-accent)" stop-opacity=".23"/><stop offset="1" stop-color="var(--ui-accent)" stop-opacity="0"/></linearGradient></defs><path class="chart-grid" d="M0 10H600M0 62H600M0 114H600M0 166H600"/><path data-chart-area fill="url(#${id})" d="M0 145 C30 145 35 122 65 128 S100 144 125 105 S170 125 200 91 S230 97 260 73 S300 105 325 63 S370 80 400 51 S455 75 480 35 S520 40 550 20 S585 28 600 10 V180 H0Z"/><path class="chart-line" data-chart-line d="M0 145 C30 145 35 122 65 128 S100 144 125 105 S170 125 200 91 S230 97 260 73 S300 105 325 63 S370 80 400 51 S455 75 480 35 S520 40 550 20 S585 28 600 10"/></svg></div><div class="chart-labels" data-chart-labels><span>01 set</span><span>06 set</span><span>11 set</span><span>16 set</span><span>21 set</span><span>26 set</span></div></div>`;}
function table(){return `<div class="table-wrap"><table class="data-table"><caption>Atividades recentes · dados de demonstração</caption><thead><tr><th scope="col">Projeto</th><th scope="col">Categoria</th><th scope="col">Status</th><th scope="col">Progresso</th></tr></thead><tbody>${[['Agente de atendimento','IA','Ativo','success',85],['Painel de resultados','Dados','Em revisão','warning',64],['Nova landing page','Design','Concluído','info',100]].map(([name,cat,status,kind,value],i)=>`<tr><td><span class="table-person"><img src="assets/images/avatar-${i+1}.webp" width="26" height="26" alt="">${name}</span></td><td>${cat}</td><td>${badge(status,kind)}</td><td><div class="row"><div class="progress" role="progressbar" aria-label="${name}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${value}" style="width:70px;--progress:${value}%"><span></span></div><span>${value}%</span></div></td></tr>`).join('')}</tbody></table></div>`;}
function dashboard(){const id='dash-'+(++sequence);return `<div class="dashboard surface" data-dashboard><div class="dashboard-top"><span class="dashboard-logo">${icon('layers')} Asimov Workspace ${badge('DEMO','accent')}</span><div class="row"><span class="muted" style="font-size:10px">Meu workspace</span>${button('','btn--square',`aria-label="Notificações" data-toast="Nenhuma nova notificação."`,'bell')}</div></div><div class="dashboard-shell"><div class="dashboard-side" role="tablist" aria-label="Área do aplicativo"><button type="button" role="tab" id="${id}-overview" aria-selected="true" aria-controls="${id}-panel" data-dashboard-view="overview">${icon('grid')} Visão geral</button><button type="button" role="tab" id="${id}-projects" aria-selected="false" tabindex="-1" aria-controls="${id}-panel" data-dashboard-view="projects">${icon('folder')} Projetos</button><button type="button" role="tab" id="${id}-team" aria-selected="false" tabindex="-1" aria-controls="${id}-panel" data-dashboard-view="team">${icon('users')} Comunidade</button></div><div class="dashboard-body" role="tabpanel" id="${id}-panel" aria-labelledby="${id}-overview"><div class="dashboard-heading"><div><h3 data-dashboard-title>Visão geral do workspace</h3><p data-dashboard-subtitle>Indicadores do período selecionado.</p></div><div class="segmented" aria-label="Período do gráfico"><button type="button" data-period="7" aria-pressed="false">7 dias</button><button type="button" data-period="30" aria-pressed="true">30 dias</button><button type="button" data-period="90" aria-pressed="false">90 dias</button></div></div><div class="grid-3">${[['Alunos ativos','2.840','+18,6%','users'],['Projetos criados','128','+24,2%','folder'],['Taxa de conclusão','94,8%','+6,4%','chart']].map(([label,value,note,glyph],i)=>`<div class="metric"><span class="metric-label">${label}${icon(glyph)}</span><strong class="metric-value" data-metric="${i}">${value}</strong><span class="metric-note"><b>${note}</b> vs. período anterior</span></div>`).join('')}</div><div data-dashboard-chart>${chart()}</div><div data-dashboard-table hidden style="margin-top:20px">${table()}</div><div data-dashboard-team hidden class="row surface surface-pad" style="margin-top:20px">${avatars()}<div><h4 style="margin:0 0 6px">Membros do workspace</h4><p class="muted" style="font-size:12px;margin:0">6 membros ativos neste workspace de demonstração.</p></div></div></div></div></div>`;}
function faq(items){return `<div class="faq-accordion">${items.map(([q,a])=>{const id='faq-'+(++sequence);return `<div class="faq-item"><h3 style="margin:0"><button class="faq-trigger" type="button" aria-expanded="false" aria-controls="${id}" id="${id}-trigger"><span class="faq-question">${q}</span><span class="faq-icon">${icon('plus')}</span></button></h3><div class="faq-body" id="${id}" role="region" aria-labelledby="${id}-trigger" inert><div class="faq-body-inner"><div class="faq-content"><p>${a}</p></div></div></div>`;}).join('')}</div>`;}
function specimen(id,label,html){return `<div class="specimen"><div class="specimen-label"><span>${label}</span></div><div id="${id}" data-snippet>${html}</div></div>`;}
function shellSpecimen(){return `<footer class="site-footer"><div class="site-footer__watermark" aria-hidden="true">ASIMOV</div><div class="site-footer__inner"><div class="site-footer__grid"><div class="site-footer__brand"><a href="index.html" aria-label="Asimov"><img src="assets/images/logo.svg" alt="Asimov" width="79" height="24"></a><p class="site-footer__tagline">Referências de interface da Asimov Academy.</p><div class="site-footer__social-list"><a class="site-footer__social-link" href="AGENTS.md" aria-label="Guia de integração">${icon('code')}</a><a class="site-footer__social-link" href="#assets" aria-label="Biblioteca de assets">${icon('grid')}</a></div></div>${[['Explore',[['Layouts','index.html'],['Components','components.html']]],['Fundamentos',[['Cores','#foundations'],['Tipografia','#foundations']]],['Recursos',[['Backgrounds','#backgrounds'],['Assets','#assets']]],['Comece aqui',[['Starter','starter.html'],['Guia para IA','AGENTS.md']]]].map(([title,links])=>`<nav aria-label="Rodapé: ${title}"><h3 class="site-footer__nav-title">${title}</h3><ul class="site-footer__nav-list">${links.map(([label,href])=>`<li><a href="${href}">${label}</a></li>`).join('')}</ul></nav>`).join('')}</div><div class="site-footer__bottom"><p>© 2026 Asimov · Exemplo de estrutura de rodapé.</p></div></div></footer>`;}
const sections=[];
function section(id,title,desc,html,origin='Home original'){sections.push({id,title});return `<section class="library-section" id="${id}" data-library-section><header><div><h2>${title}</h2><p>${desc}</p></div>${badge(origin,origin==='Home original'?'accent':'info')}</header>${html}</section>`;}
function head(title){return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><meta name="description" content="Design system portátil da Asimov Academy: identidade Lumina, componentes interativos, layouts e animações locais."><meta name="robots" content="noindex,nofollow"><title>${title} · Asimov Design System</title><link rel="icon" href="assets/images/logo.svg" type="image/svg+xml"><link rel="preload" href="assets/fonts/inter-latin-400.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="assets/fonts/inter-latin-500.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="assets/css/design-system.css"><script src="assets/js/themes.js" defer></script><script src="assets/js/rain-shaders.js" defer></script><script src="assets/js/rain.js" defer></script><script src="assets/js/aurora.js" defer></script><script src="assets/js/system.js" defer></script></head>`;}
function nav(current){return `<a class="skip-link" href="#main">Ir para o conteúdo</a><header class="ds-nav"><a class="ds-brand" href="index.html" aria-label="Asimov Academy"><img src="assets/images/logo.svg" alt="Asimov" width="79" height="24"></a><nav class="ds-nav-links" aria-label="Principal"><a href="index.html" ${current==='layouts'?'aria-current="page"':''}>${icon('layers')} Layouts</a><a href="components.html" ${current==='components'?'aria-current="page"':''}>${icon('grid')} Components</a></nav><div class="library-theme-control"><label for="component-theme">Cores</label><div class="library-theme-control__select"><span class="library-theme-control__swatch" aria-hidden="true"></span><select id="component-theme" data-theme-select aria-label="Cor da página" aria-describedby="component-theme-help">${themeOptions}</select></div><p class="sr-only" id="component-theme-help">Botões, cards, gráficos e backgrounds seguem esta paleta.</p><span class="sr-only" data-theme-status role="status">Tema: Teal</span></div></header>`;}
function footer(){return `<footer class="ds-footer"><div class="container-ds"><div class="row"><img src="assets/images/logo.svg" alt="Asimov" width="65" height="20"><span>Asimov Academy · Biblioteca de interface</span></div><div class="row"><a href="AGENTS.md">Guia para IA ${icon('arrow')}</a><span>2026 · v1.0</span></div></div></footer>`;}
function shared(){return `<div class="toast" role="status" aria-live="polite" aria-atomic="true" id="toast"></div><dialog class="dialog" id="demo-dialog" aria-labelledby="dialog-title"><button type="button" class="btn btn--square dialog-close" data-close-dialog aria-label="Fechar modal">${icon('close')}</button><p class="eyebrow">Preview interativo</p><h2 id="dialog-title">Exemplo de diálogo</h2><p data-dialog-copy>Este é um componente de demonstração. Conecte esta ação à lógica do seu produto.</p><form method="dialog"><button class="btn btn--solid" value="close">Entendi ${icon('check')}</button></form></dialog><button class="help-fab" type="button" data-dialog="Guia rápido" aria-label="Ajuda sobre o design system">${icon('message')}</button>`;}
const aurora=(composite=false)=>`<div class="aura-background${composite?' aura-background--composite':''}" data-aura aria-hidden="true"></div>`;
const landscape=()=>`<div class="landscape-layer" aria-hidden="true"><img class="landscape-layer__image" src="assets/images/landscape-1280.webp" srcset="assets/images/landscape-768.webp 768w, assets/images/landscape-1280.webp 1280w" sizes="100vw" width="1280" height="720" alt="" decoding="async"></div>`;
const homeBackground=()=>aurora(true)+landscape();
function backgroundSpecimen(id,label,markup,kind,title,description){
  const animated=kind!=='landscape';
  return `<div class="specimen background-example" data-background-example="${kind}"><div class="specimen-label"><span>${label}</span></div>
    <div class="background-lab" data-background-preview>${markup}<div class="background-lab__copy"><p class="eyebrow" style="justify-content:center">Background Asimov</p><h3 class="text-gradient-silver">${title}</h3><p>${description}</p></div></div>
    ${animated?`<div class="background-controls">${kind==='rain'?`<label for="${id}-intensity">Intensidade da chuva <output id="${id}-intensity-output" for="${id}-intensity" data-intensity-output>1.0</output><input id="${id}-intensity" data-rain-intensity type="range" min="0.2" max="2" step="0.1" value="1" aria-describedby="${id}-intensity-output"></label>`:''}${button('Pausar','btn--small',`data-background-pause aria-pressed="false" aria-label="Pausar ${title}"`)}</div>`:''}
    <p class="background-example__status muted" data-background-status role="status">${animated?'Animação local · pausa fora da área visível.':'Imagem original · composição estática.'}</p><template id="${id}" data-snippet>${markup}</template></div>`;
}
function layoutPicker(current){return `<nav class="layout-picker container-ds" aria-label="Exemplos de layouts"><span>Layouts</span><a href="index.html" ${current==='aura'?'aria-current="page"':''}>Principal · Aura</a><a href="cadence-rain.html" ${current==='rain'?'aria-current="page"':''}>Workspace · Cadence Rain ${icon('arrow')}</a></nav>`;}
const layout=`${head('Layouts')}<body class="library-themed">${nav('layouts')}${homeBackground()}<div class="site-grid" aria-hidden="true"></div><main id="main">${layoutPicker('aura')}<section class="hero-ds container-ds" id="hero"><div class="hero-ds__grid"><div class="reveal"><p class="eyebrow">Referência de interface <span class="badge">v1.0</span></p><h1>Design System <span class="text-gradient-silver">Asimov Academy</span></h1><p class="hero-ds__intro text-copy">Referência visual para landing pages e aplicativos da Asimov Academy. Tipografia, cores, componentes e layouts em uma biblioteca reutilizável.</p><div class="row">${glow('Ver componentes','components.html')}<a class="btn btn--ghost" href="#features">Ver layouts ${icon('arrow')}</a></div><div class="hero-ds__foot">${avatars()}<span>Biblioteca de referência · edição 2026</span></div></div></div><div class="hero-divider"><span>Fundamentos e recursos</span><span>${icon('type')} Tipografia</span><span>${icon('palette')} Cores</span><span>${icon('grid')} Componentes</span><span>${icon('rain')} Movimento</span><span>${icon('code')} Código portátil</span></div></section><div class="layouts-content"><section class="section-ds container-ds" id="features">${heading('01','Componentes','Componentes<br><span class="text-gradient-silver">e padrões de interface.</span>','Exemplos de composição com os estilos da Asimov Academy: botões, cards, superfícies, estados e efeitos de fundo.')}<div class="grid-3 feature-cards reveal">${course('Interações<br>e estados','Botões, mensagens e transições para indicar ações e estados da interface.','cpu',null,'01 / INTERAÇÃO')}${course('Dados<br>e indicadores','Padrões de apresentação para métricas, tabelas e gráficos.','chart',null,'02 / INFORMAÇÃO')}${course('Identidade<br>e consistência','Cores, transparências e bordas definidas para uso consistente entre páginas.','palette',null,'03 / IDENTIDADE')}</div><div class="bento reveal"><article class="surface media-tile"><span class="eyebrow" style="margin-bottom:16px">Plataforma Asimov</span><h3>Referências da plataforma.</h3><p>Exemplo de aplicação dos componentes no ambiente de aprendizagem.</p><img src="assets/images/platform-1.png" alt="Interface original da plataforma Asimov Academy" loading="lazy" width="900" height="490"></article><div class="stack"><article class="surface feature-mini"><span class="icon-stage">${icon('rain')}</span><div><h3>Fundos e efeitos.</h3><p>Aurora boreal e paisagem original mescladas em um único fundo. Chuva Cadence como alternativa.</p></div><a href="cadence-rain.html" class="feature-link">Ver layout com Cadence Rain ${icon('arrow')}</a></article><article class="surface feature-mini"><span class="icon-stage">${icon('code')}</span><div><h3>Arquivos para reutilização.</h3><p>Fontes, imagens e interações incluídas na pasta, sem dependência do projeto principal.</p></div><a href="AGENTS.md" class="feature-link">Consultar guia de uso ${icon('arrow')}</a></article></div></div></section><section class="section-ds container-ds" id="applications">${heading('02','Aplicativos','Layouts<br><span class="text-gradient-silver">para aplicativos.</span>','Exemplo de dashboard com navegação, indicadores e gráficos. Os dados e as interações são demonstrativos.')}<div class="reveal">${dashboard()}</div><div class="row between" style="margin-top:20px;color:#79878b;font-size:11px"><span>${icon('info')} Dados ilustrativos · explore as abas e os períodos</span><a class="btn btn--link" href="components.html#data">Ver componentes de dados ${icon('arrow')}</a></div></section><section class="section-ds container-ds" id="pricing">${heading('03','Planos e garantia','Planos<br><span class="text-gradient-silver">e condições.</span>','Referência de apresentação para preços, comparação de recursos e informações de garantia.')}<div class="reveal">${pricing()}</div><p class="pricing-demo-note">Planos e valores demonstrativos para visualizar o layout. Nenhuma compra é realizada.</p><div class="reveal">${guarantee()}</div></section></div></main>${footer()}${shared()}</body></html>`;

let library='';
library+=section('foundations','01 / Fundamentos','Tokens extraídos da home. Inter conduz a interface; prata vertical e teal dão a assinatura visual.',`<div class="row between" style="margin-bottom:22px"><span class="muted" style="font-size:12px">Clique em uma cor para copiar o valor.</span></div><div class="color-grid">${[['Accent','#14b8a6','--ui-accent'],['Dark','#0d9488','--ui-accent-dark'],['Light','#2dd4bf','--ui-accent-light'],['Glow','#5eead4','--ui-accent-glow'],['Surface','#050505','--color-surface'],['Elevated','#0a0a0a','--color-surface-elevated'],['Copy','#b4b4b4','--color-text-copy'],['Border','rgba(255,255,255,0.08)','--border-subtle']].map(([label,value,key])=>`<button class="swatch" type="button" data-copy-token="${key}" style="--swatch:var(${key})"><span class="swatch-color"></span><span class="swatch-label">${label}<small data-token-label="${key}">${value}</small></span></button>`).join('')}</div><h3 class="spec-label">Paletas disponíveis · clique para copiar a cor</h3><div class="row">${paletteNames.map(([key,label])=>`<button class="badge" type="button" data-copy-text="${tokens.themes[key].accent}" style="color:${tokens.themes[key]['accent-light']}"><span class="status-dot" style="background:${tokens.themes[key].accent}"></span>${label}</button>`).join('')}</div><div class="specimen"><div class="specimen-label"><span>Inter / 400 · 500 · 600 · 700</span><a class="copy-btn" href="tokens.json" download>${icon('download')} Tokens JSON</a></div><div class="type-row"><small>DISPLAY<br>80px / 1.04 / −.065em</small><p class="type-hero text-gradient-silver">Design System Asimov</p></div><div class="type-row"><small>HEADING<br>40px / 1.08 / 500</small><p class="type-heading">Componentes de interface</p></div><div class="type-row"><small>BODY<br>18px / 1.65 / 400</small><p class="text-copy">Referências de tipografia, espaçamento e cor para compor páginas e aplicativos.</p></div><div class="type-row"><small>CARD<br>16px / 1.65 / 400</small><p class="text-card">Texto de referência para o conteúdo dos cards.</p></div><div class="type-row"><small>EYEBROW<br>11px / .16em / 700</small><p class="section-badge"><span class="section-badge__dot"></span>REFERÊNCIA DE COMPONENTE</p></div></div><h3 class="spec-label">Superfícies e raios</h3><div class="grid-3">${[['8px / controles','8px'],['16px / painéis','16px'],['24px / cards','24px']].map(([s,r])=>`<div class="surface surface-pad" style="border-radius:${r};font-size:11px;color:#a5b3b0">${s}</div>`).join('')}</div>`);
library+=section('buttons','02 / Botões e ações','O CTA glass conserva o gradiente cônico de 3s, o miolo translúcido e o glow original. Passe o mouse e navegue com Tab.',specimen('button-set','ButtonGlow + Cadence CTA',`<div class="row">${glow('Começar agora','#buttons','data-dialog="ButtonGlow"')}${button('Ação principal','btn--solid','data-toast="Ação principal acionada."','arrow')}${button('Secundário','','data-toast="Ação secundária acionada."')}${button('Ghost','btn--ghost','data-toast="Ação discreta acionada."','arrow')}</div>`)+specimen('button-states','Extensões / estados de aplicação',`<div class="row">${button('Salvar alterações','btn--solid','data-loading-button','check')}${button('Indisponível','','disabled')}${button('<span class="spinner" aria-hidden="true"></span> Processando','','disabled aria-busy="true"')}${button('Excluir','btn--danger','data-dialog="Confirmar ação"')}${button('','btn--square','aria-label="Adicionar item" data-toast="Item de demonstração adicionado."','plus')}<span class="tooltip-wrap">${button('','btn--square','aria-label="Informações" aria-describedby="tip-demo"','info')}<span id="tip-demo" role="tooltip" class="tooltip">Feedback sem interromper o fluxo</span></span></div>`));
library+=section('cards','03 / Cards e superfícies','Mesmas camadas da home: beam superior, halo radial, pontos, transparência e hover com elevação, rotação e escala.',specimen('course-cards','CoursesBlock / tema global',`<div class="grid-3">${course('Formação<br>Engenheiros de IA','Do zero a seus primeiros agentes IA usando Python.','cpu',null,'49h','#cards')}${course('Formação Analista<br>de Dados','Analise dados profissionalmente usando Python.','chart',null,'24h','#cards')}${course('Formação<br>AI Designer','Crie sites com ferramentas de design e IA.','palette',null,'15h','#cards')}</div>`)+specimen('benefit-cards','GlassBenefitCard / pedestal + halo + borda mascarada',`<div class="grid-3">${benefit('Suporte e atualizações','Canais de suporte e materiais de referência.','message')}${benefit('Comunidade ativa','Espaço de discussão e troca de referências.','users','light')}${benefit('Conteúdo autoral','Conteúdo organizado por tema e nível de conhecimento.','book','glow')}</div>`)+specimen('media-card','PlatformBlock / mídia original',`<div class="platform-media-card"><span class="platform-media-card__beam"></span><span class="platform-media-card__glow"></span><span class="platform-media-card__dots"></span><div class="platform-media-card__inner"><img class="platform-row__img" src="assets/images/platform-2.png" alt="Projetos exclusivos na plataforma Asimov" width="900" height="500" loading="lazy"></div></div>`));
library+=section('people','04 / Pessoas e prova social','Avatares sobrepostos e o card de instrutor com foto, máscara e verso em gradiente. O carrossel aceita toque, teclado e botões.',specimen('social-proof','HeroSocialProof',social())+specimen('instructors','InstructorsBlock / hover e foco',`<div class="instructors-section" style="--instructors-card-width:240px;--instructors-card-height:320px;--instructors-card-bg:#111;--instructors-cyan:var(--ui-accent);--instructors-cyan-deep:var(--ui-accent-dark)"><div class="row between"><p class="muted" style="font-size:12px;margin:0">Equipe de instrutores.</p><div class="row">${button('←','btn--square','data-carousel-prev aria-label="Instrutor anterior"')}${button('→','btn--square','data-carousel-next aria-label="Próximo instrutor"')}</div></div><div class="instructor-strip" tabindex="0" aria-label="Carrossel de instrutores">${instructor('Rodrigo Tadewald','Python e IA','rodrigo','Engenheiro Químico formado pela UFRGS. Sócio-fundador da Asimov Academy e instrutor de Python e Inteligência Artificial.')}${instructor('Juliano Faccioni','Python e Dados','juliano','Doutor em Biologia Celular e Molecular pela UFRGS. Instrutor de Python e sócio da Asimov Academy.')}${instructor('Samuel Sublate','Automações','samuel','Programador desde 2019, especializado em automações. Desenvolvedor de software e instrutor na Asimov Academy.')}${instructor('Lucas Petry','Design com IA','lucas','Profissional de marketing desde 2019. Instrutor de Vibe Design, criação de sites e geração de imagens com IA.')}</div></div>`));
library+=section('backgrounds','05 / Backgrounds e movimento','Quatro composições renderizadas para comparar: Aura com imagem, Cadence Rain, Aura sem imagem e paisagem estática. Todas seguem o seletor de cores da navbar.',`
${backgroundSpecimen('home-background-snippet','01 / Aura + paisagem · background principal',homeBackground(),'aura-landscape','Aura + imagem','Aurora boreal, paisagem e camadas de composição.')}
${backgroundSpecimen('rain-snippet','02 / Cadence Rain · background alternativo','<div class="cadence-rain-bg" data-rain aria-hidden="true"></div>','rain','Cadence Rain','Chuva WebGL com o shader e as camadas originais.')}
${backgroundSpecimen('aurora-snippet','03 / Aura sem imagem · aurora.js',aurora(),'aura','Aura sem imagem','Aurora boreal do Unicorn Studio, sem a paisagem.')}
${backgroundSpecimen('landscape-snippet','04 / Imagem estática · transparência + gradiente + glow',landscape(),'landscape','Imagem estática','Paisagem original com transparência, gradiente e glow.')}
<div class="row" style="margin-top:24px"><a class="copy-btn" href="assets/source/aura-default.json" download>${icon('download')} Cena Aurora / Unicorn</a><a class="copy-btn" href="assets/source/cadence-rain-original.ts" download>${icon('download')} Fonte Cadence</a>${button('Repetir entrada','btn--small','data-replay')}</div><div class="grid-3 motion-grid" style="margin-top:18px"><div class="surface" data-replay-target><div>${icon('layers')}<p>Reveal · 1s · blur 6px</p></div></div><div class="surface"><div class="float-demo">${icon('spark')}<p>Flutuação · 4s</p></div></div><div class="surface"><div>${glow('Glow','#backgrounds')}<p>Borda cônica · 3s</p></div></div></div>`);
