library+=section('feedback','09 / Feedback e estados','Feedback visível para confirmar, orientar, carregar ou recuperar. Modal nativo com foco, Escape e retorno ao acionador.',specimen('status-set','Badges semânticos',`<div class="row">${badge('Publicado','success')}${badge('Em análise','warning')}${badge('Erro na conexão','danger')}${badge('Atualização disponível','info')}${badge('Novo','accent')}${badge('Rascunho','neutral')}</div>`)+specimen('alerts','Mensagens contextuais',`<div class="stack"><div class="alert" role="status">${icon('check')}<div>Seu projeto está pronto.<p>Todos os componentes estão disponíveis para uso.</p></div></div><div class="alert" style="--alert-color:var(--warning)">${icon('info')}<div>Revise as informações.<p>Confira os campos antes de continuar.</p></div></div><div class="alert" style="--alert-color:var(--danger)">${icon('info')}<div>Não foi possível concluir.<p>Tente novamente. Seus dados permanecem no formulário.</p></div></div></div>`)+specimen('loading-empty','Loading / vazio / ações de feedback',`<div class="grid-2"><div class="surface surface-pad"><div class="skeleton-card" role="status" aria-label="Carregando conteúdo"><div class="skeleton skeleton-avatar"></div><div class="stack" style="flex:1;gap:9px"><div class="skeleton" style="width:80%"></div><div class="skeleton" style="width:55%"></div></div></div><div class="row" style="margin-top:30px">${button('Abrir modal','','data-dialog="Detalhes do componente"')}${button('Ver toast','btn--small','data-toast="Alterações salvas com sucesso."')}</div></div><div class="surface empty-state">${icon('folder')}<h3>Nenhum projeto cadastrado</h3><p>Os projetos cadastrados serão listados nesta seção.</p>${button('Criar primeiro projeto','btn--small','data-dialog="Seu primeiro projeto"','plus')}</div></div>`),'Extensão para apps');
library+=section('conversion','10 / Conversão e garantia','Pricing Cadence preservado, incluindo a borda mascarada, blur e destaque. O selo de garantia mantém sua rotação de 30 segundos.',specimen('pricing-example','Index4PricingSection / planos demonstrativos',pricing())+specimen('guarantee-example','GuaranteeBlock / selo orbital',guarantee())+specimen('announcement-example','Barra de campanha / adaptação sem oferta real',`<div class="announcement"><span>${icon('spark')} Exemplo de aviso com prazo.</span><span class="countdown" data-countdown data-seconds="86400" aria-label="Contagem regressiva de demonstração"><span>01d</span><span>00h</span><span>00m</span><span>00s</span></span><a class="btn btn--small" href="starter.html">Ver exemplo ${icon('arrow')}</a></div>`));
library+=section('faq','11 / Accordion e FAQ','Transição original de grid, brilho na borda e ícone que gira. Botões semânticos com estado expandido e conteúdo acessível.',specimen('faq-example','FaqBlock',faq([['Funciona fora do projeto Astro?','Sim. Copie a pasta inteira e abra index.html. Todos os caminhos são relativos, os scripts são clássicos e as fontes, imagens e bibliotecas estão dentro de assets.'],['Como levo a chuva para outro projeto?','Use starter.html como base. Carregue assets/css/design-system.css e os scripts rain-shaders.js e rain.js, nesta ordem. Inclua um elemento com class="cadence-rain-bg" e data-rain.'],['Como a identidade é preservada?','As regras visuais originais estão em source-components.css, source-pricing.css e source-button-glow.css. Os novos controles usam os mesmos tokens em tokens.css.'],['E se as animações estiverem desativadas?','A preferência de movimento reduzido do sistema é respeitada. O conteúdo permanece visível, e os efeitos WebGL usam um fallback visual estático.']])));
library+=section('assets','12 / Assets locais','Fontes, marca, imagens da plataforma, paisagens e retratos usados na home. Os arquivos originais ficam disponíveis para reutilização.',`<div class="grid-3 asset-grid">${[['logo.svg','Logo / SVG'],['landscape-1280.webp','Landscape / 1280'],['landscape-768.webp','Landscape / 768'],...[1,2,3,4,5,6].map(i=>[`platform-${i}.png`,`Plataforma / ${i}`])].map(([file,label])=>`<a class="asset-thumb" href="assets/images/${file}" download><img src="assets/images/${file}" alt="${label}" loading="lazy" width="250" height="140"><span>${label}${icon('download')}</span></a>`).join('')}</div><h3 class="spec-label">Retratos e avatares</h3><div class="grid-4 asset-grid">${['rodrigo','juliano','samuel','lucas','adriano','viviane','daniel','ana-maria','mykael','cassio','marcelo','otavio','vitor'].map(name=>`<a class="asset-thumb portrait-asset" href="assets/images/instructor-${name}.${['marcelo','otavio','vitor'].includes(name)?'png':'webp'}" download><img src="assets/images/instructor-${name}.${['marcelo','otavio','vitor'].includes(name)?'png':'webp'}" alt="Retrato de ${name}" loading="lazy" width="160" height="115"><span>${name}${icon('download')}</span></a>`).join('')}</div><div class="row" style="margin-top:25px">${avatars()}<span class="muted" style="font-size:11px">6 avatares / assets/images/avatar-1.webp … avatar-6.webp</span></div><h3 class="spec-label">Ícones locais / SVG inline</h3><div class="row">${Object.keys(paths).map(name=>`<button type="button" class="btn btn--square" data-copy-text="${esc(icon(name))}" aria-label="Copiar ícone ${name}" title="${name}">${icon(name)}</button>`).join('')}</div><p class="muted" style="font-size:11px;margin-top:15px">Traço de 1,5px. Primitivos de Icon.astro preservados; ícones adicionais são adaptações locais de traço. Clique para copiar o SVG.</p>`);
