const footerMarkup=shellSpecimen().replaceAll('site-footer__nav-title','site-footer__col-title').replaceAll('site-footer__nav-list','site-footer__links').replaceAll('site-footer__bottom','site-footer__bar').replaceAll('<li><a href=','<li><a class="site-footer__link" href=');
library=library.replace(/<\/section>$/, '<h3 class="spec-label">Rodapé completo / estrutura da home</h3>'+specimen('footer-example','Footer / marca + colunas + watermark',footerMarkup)+'</section>');
const components=`${head('Components')}<body class="library-themed">${nav('components')}${homeBackground()}<div class="site-grid" aria-hidden="true"></div><main id="main"><div class="library-head"><div class="container-ds"><div><h1>Biblioteca de <span class="text-gradient-silver">componentes.</span></h1><p>Consulte os estilos, estados e exemplos de uso. Cada componente inclui uma referência visual e, quando aplicável, o HTML para reutilização.</p></div></div></div><div class="container-ds library-layout"><aside class="library-sidebar"><label for="component-search">Encontrar componente</label><input type="search" id="component-search" placeholder="Buscar na biblioteca…" aria-controls="library-content"><nav aria-label="Seções de componentes">${sections.map(({id,title},i)=>`<a href="#${id}">${title.split(' / ')[1]}<span>${String(i+1).padStart(2,'0')}</span></a>`).join('')}</nav><small>HOME ASIMOV → LUMINA<br>Tokens originais, código local.<br>Uso em páginas e aplicativos.</small></aside><div class="library-main" id="library-content"><p class="library-no-results" id="library-no-results" role="status" hidden>Nenhum componente encontrado. Tente “card”, “botão” ou “dados”.</p>${library}</div></div></main>${footer()}${shared()}</body></html>`;
const starter=`${head('Starter')}<body class="library-themed">${homeBackground()}${nav('layouts')}<main id="main" class="container-ds"><section class="section-ds" style="min-height:70vh;display:flex;flex-direction:column;justify-content:center;align-items:start"><p class="eyebrow">Template inicial</p><h1 style="font-size:clamp(42px,7vw,80px);max-width:800px;line-height:1.04">Template inicial<br><span class="text-gradient-silver">Asimov Academy.</span></h1><p class="text-copy" style="max-width:500px">Estrutura básica com estilos, fontes e fundo configurados. Substitua o conteúdo e adicione os componentes necessários ao projeto.</p>${glow('Consultar a biblioteca','components.html')}</section><section class="section-ds"><div class="grid-3">${benefit('Clareza','Organização do conteúdo por função.','layers')}${benefit('Consistência','Tokens compartilhados entre os componentes.','palette','light')}${benefit('Movimento','Transições para indicar ações e estados.','spark','glow')}</div></section></main>${footer()}${shared()}</body></html>`;
const cadenceLayout=`${head('Workspace · Cadence Rain')}<body class="library-themed">${nav('layouts')}<div class="cadence-rain-bg" data-rain aria-hidden="true"></div><div class="site-grid" aria-hidden="true"></div><main id="main">${layoutPicker('rain')}
<section class="cadence-layout-hero container-ds" aria-labelledby="workspace-title"><div class="cadence-layout-hero__copy"><p class="eyebrow">Layout de aplicativo · Cadence Rain</p><h1 id="workspace-title">Seus projetos,<br><span class="text-gradient-silver">em um só lugar.</span></h1><p class="text-copy">Organize o trabalho, acompanhe as entregas e consulte os indicadores do seu time em um ambiente integrado.</p><div class="row">${glow('Explorar workspace','#workspace')}<a class="btn btn--ghost" href="components.html#backgrounds">Ver background ${icon('arrow')}</a></div><p class="cadence-layout-note">Interface demonstrativa · dados ilustrativos</p></div>
<aside class="surface cadence-activity" aria-labelledby="activity-title"><div class="row between"><span class="cadence-activity__brand">${icon('layers')} Asimov Workspace</span>${badge('DEMO')}</div><div class="cadence-activity__heading"><div><p class="eyebrow">Visão do time</p><h2 id="activity-title">Projetos em andamento</h2></div><span class="cadence-activity__count">03</span></div><ul class="cadence-activity__list">${[['cpu','Agente de atendimento','Integração com a base de conhecimento','Em revisão'],['chart','Painel de resultados','Indicadores e relatórios do período','Em andamento'],['palette','Portal de conteúdo','Componentes e organização das páginas','Planejado']].map(([glyph,title,description,status])=>`<li><span class="cadence-activity__icon">${icon(glyph)}</span><div><h3>${title}</h3><p>${description}</p><span>${status}</span></div></li>`).join('')}</ul><div class="cadence-activity__footer">${avatars()}<span>6 pessoas no workspace</span></div></aside></section>
<div class="container-ds cadence-layout-meta"><span>${icon('rain')} Cadence Rain</span><span>Chuva WebGL · camadas originais</span><a href="index.html">Ver layout com Aura ${icon('arrow')}</a></div>
<section class="section-ds container-ds" id="workspace">${heading('01','Workspace','Acompanhe o trabalho.<br><span class="text-gradient-silver">Consulte os resultados.</span>','Navegação, métricas e gráficos sobre o fundo Cadence Rain. Explore as abas e os períodos para ver os estados da interface.')}${dashboard()}<div class="row between cadence-layout-bottom"><span>O background continua visível entre as superfícies.</span><a class="btn btn--link" href="components.html#data">Consultar componentes ${icon('arrow')}</a></div></section>
<section class="container-ds cadence-layout-callout surface"><div><p class="eyebrow">Mesmos componentes, outra composição</p><h2>Uma base para páginas<br><span class="text-gradient-silver">e aplicativos.</span></h2><p class="text-copy">Este layout mantém as fontes, superfícies e interações da biblioteca, com Cadence Rain como fundo alternativo.</p></div>${glow('Ver biblioteca','components.html')}</section></main>${footer()}${shared()}</body></html>`;
for(const [file,html] of [['index.html',layout],['components.html',components],['starter.html',starter],['cadence-rain.html',cadenceLayout]]) await fs.writeFile(path.join(root,file),html.replaceAll('><','>\n<'));
await fs.writeFile(path.join(root,'assets','images','icons.svg'),`<svg xmlns="http://www.w3.org/2000/svg">${Object.entries(paths).map(([id,p])=>`<symbol id="${id}" viewBox="0 0 24 24">${p}</symbol>`).join('')}</svg>`);
console.log('Generated index.html, components.html, starter.html, cadence-rain.html and local icons.');
